/**************************************************************************/
/*                                                                        */
/*  BOARD SUPPORT                                          RELEASE        */
/*                                                                        */
/*    timer.c                                          Cortex-R52/GNU     */
/*                                                           6.5.2        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    Arm generic timer tick for Cortex-R52 on the Armv8-R AEM FVP.       */
/*                                                                        */
/*    Two model behaviours make this longer than a bare timer setup, both */
/*    confirmed by reading the hardware rather than assumed:              */
/*                                                                        */
/*      1. The system counter is STOPPED at reset (CNTCR = 0, CNTCV = 0). */
/*         The model documents that firmware is expected to start it, so  */
/*         the counter control frame is enabled here.  Without this the   */
/*         timer never counts and no tick is ever delivered.              */
/*      2. CNTFRQ resets to ZERO.  It is writable only at the highest     */
/*         implemented exception level, so entry.S programs it at EL2;    */
/*         this file only reads it.  Deriving the tick interval from an   */
/*         unprogrammed CNTFRQ would divide by zero.                      */
/*                                                                        */
/*    EL1 access to the physical timer and counter also depends on        */
/*    CNTHCTL.PL1PCEN/PL1PCTEN, which reset disabled and are set by       */
/*    entry.S at EL2; otherwise these accesses would trap to EL2.         */
/*                                                                        */
/*  MISRA C:2012 deviations (justified)                                   */
/*                                                                        */
/*    Directive 4.3 -- the generic timer is only reachable through CP15   */
/*      registers; every such access is encapsulated in an accessor below.*/
/*                                                                        */
/**************************************************************************/

#include "tx_api.h"
#include "platform.h"
#include "timer.h"

/* Counter control frame (CNTControlBase).                                */

#define CNTCR                   0x0000U
#define CNTCR_EN                (1UL << 0)
#define CNTSR                   0x0004U

/* CNTP_CTL bits.                                                         */

#define CNTP_CTL_ENABLE         (1UL << 0)
#define CNTP_CTL_IMASK          (1UL << 1)

static unsigned long tick_interval;


/**************************************************************************/
/*  Generic timer accessors (AArch32 CP15).                               */
/**************************************************************************/

static unsigned long read_cntfrq(void)
{
    unsigned long value;
    __asm__ volatile("mrc p15, 0, %0, c14, c0, 0" : "=r"(value));
    return value;
}

static void write_cntp_tval(unsigned long value)
{
    __asm__ volatile("mcr p15, 0, %0, c14, c2, 0" : : "r"(value) : "memory");
}

static void write_cntp_ctl(unsigned long value)
{
    __asm__ volatile("mcr p15, 0, %0, c14, c2, 1" : : "r"(value) : "memory");
}

static unsigned long long read_cntpct(void)
{
    unsigned long low;
    unsigned long high;

    __asm__ volatile("mrrc p15, 0, %0, %1, c14" : "=r"(low), "=r"(high));

    return ((unsigned long long) high << 32) | (unsigned long long) low;
}


/**************************************************************************/
/*  timer_frequency                                                       */
/**************************************************************************/

unsigned long timer_frequency(void)
{
    return read_cntfrq();
}


/**************************************************************************/
/*  timer_counter                                                         */
/**************************************************************************/

unsigned long long timer_counter(void)
{
    return read_cntpct();
}


/**************************************************************************/
/*  timer_counter_enabled                                                 */
/**************************************************************************/

unsigned int timer_counter_enabled(void)
{
    return ((REG32(CNT_CONTROL_BASE + CNTCR) & CNTCR_EN) != 0UL) ? 1U : 0U;
}


/**************************************************************************/
/*  timer_reload                                                          */
/**************************************************************************/

void timer_reload(void)
{
    /* Writing CNTP_TVAL restarts the down-count, which also deasserts the
       level-sensitive timer output.  */

    write_cntp_tval(tick_interval);
}


/**************************************************************************/
/*  timer_init                                                            */
/**************************************************************************/

void timer_init(void)
{
    unsigned long frequency;

    /* Start the system counter -- it is stopped at reset on this model.  */

    REG32(CNT_CONTROL_BASE + CNTCR) |= CNTCR_EN;

    /* Derive the tick interval.  CNTFRQ was programmed at EL2; fall back to
       the known counter frequency rather than dividing by zero should that
       ever not have happened.  */

    frequency = read_cntfrq();
    if (frequency == 0UL)
    {
        frequency = (unsigned long) SYSTEM_COUNTER_HZ;
    }

    tick_interval = frequency / TX_TIMER_TICKS_PER_SECOND;

    /* Enable the timer, unmasked, and arm the first interval.  */

    write_cntp_tval(tick_interval);
    write_cntp_ctl(CNTP_CTL_ENABLE);
}
